type TooltipOwnProps = {
  content: Exclude<React.ReactNode, null | undefined | boolean>;
  trigger: React.ReactElement;
  delay?: number;
  closeDelay?: number;
  placement?: MuxUIPlacement;
  offset?: number;
  crossOffset?: number;
  shouldFlip?: boolean;
  containerPadding?: number;
  open?: boolean;
  defaultOpen?: boolean;
  disabled?: boolean;
  onOpenChange?: (open: boolean) => void;
};

type TooltipProps = TooltipOwnProps & {
  className?: string;
  anchorRef?: React.RefObject<Element | null>;
};
